core=dict(status='usable',core_gaps=[],open_details=['Remote read prefix publication identity discrepancy remains a concrete question.','Read confirmations across membership transitions, snapshot transport failures, storage crash atomicity and session deduplication remain open.'],rationale='Representative formation, authority change and old-work handling are traced through actual membership, recovery, persistence and completion owners. Usable navigation does not certify these paths.',formation=dict(explanation='The leader indexes proposals and aggregates per-voter/witness match acknowledgments into current-term commitment; followers validate the preceding term and protect the committed prefix. Commit propagates via replication and bounded heartbeats. Engine exports/persists state and queues committed entries to RSM, whose callbacks complete proposals and expose applied position. For reads, current-term commitment precedes distinct-voter heartbeat confirmation and prefix release; publication then feeds exact-context local batches, which additionally wait for application.',behavior_ids=['B-replicate','B-read-qualification','B-read-publication','B-persist','B-apply','B-client-read'],fact_ids=['F-committed','F-read-status'],source_ids=['src-quorum-commit','src-read-release','src-read-queue','src-update-order','src-rsm-application','src-read-consumer']),context=dict(explanation='Election ticks campaign only for eligible nodes with no committed-but-unapplied entries. Available votes and up-to-date logs qualify support; known-peer response filtering and term dispatch precede aggregation. Higher terms, lost quorum and self-removal can remove authority; transfer waits for a full member to catch up and has a timeout. Reset discards pending read support and remote progress but preserves log commitment. New leadership appends a no-op and reconstructs pending config state. Membership changes are applied by the RSM then reflected in Raft under raftMu; recovery reconstructs snapshot membership and saved term/vote/log before later formation.',behavior_ids=['B-authority','B-membership','B-recovery','B-persist'],fact_ids=['F-committed','F-read-status'],source_ids=['src-authority-reset','src-term-election','src-peer-boundary','src-authority-timers','src-transfer','src-rsm-config','src-config-apply','src-rsm-recovery','src-new-raft']),connection=dict(explanation='Support is owned by the current term and installed membership. Authority transitions clear volatile votes/read support/progress, while persisted term/vote and protected committed history constrain future elections and replication. Applied membership updates redefine eligible participants and quorum; election blocking prevents campaigning before committed history is consumed. Confirmed reads bridge leadership support and client consumption through request context and application position, so release and notification are separate responsibilities. Stale-term replies are rejected; forwarded pending requests have distinct context, drop/timeout handling and no implicit completion guarantee from role acquisition.',behavior_ids=['B-authority','B-membership','B-replicate','B-read-qualification','B-read-publication','B-client-read','B-apply'],fact_ids=['F-committed','F-read-status'],source_ids=['src-term-election','src-authority-reset','src-membership-raft','src-read-queue','src-read-reply','src-forward-read','src-read-consumer']))
